{
  "action": "ACCOUNT_MANAGER",
  "conditions": [
    {"attr": "customer_tier", "op": "eq", "value": "enterprise"},
    {"attr": "severity", "op": "lte", "value": 3},
    {"attr": "prior_tickets_30d", "op": "gte", "value": 5}
  ],
  "beats": [],
  "loses_to": [],
  "note": "Enterprise customers with a high ticket volume (5+ in 30 days) and non-critical severity need proactive account management to address recurring issues, even if the current ticket is low severity."
}

{
  "action": "T2_TECHNICAL",
  "conditions": [
    {"attr": "product", "op": "eq", "value": "dashboard"},
    {"attr": "severity", "op": "lte", "value": 3},
    {"attr": "off_hours", "op": "eq", "value": true}
  ],
  "beats": [],
  "loses_to": [],
